    Port of https://hg-edge.mozilla.org/mozilla-central/rev/a8d0279b32c7

    Differential Revision: https://phabricator.services.mozilla.com/D269377

diff --git a/mail/themes/shared/mail/accountManage.css b/mail/themes/shared/mail/accountManage.css
index 89372fd56ef..6ff9e70db1d 100644
--- a/mail/themes/shared/mail/accountManage.css
+++ b/mail/themes/shared/mail/accountManage.css
@@ -56,8 +56,8 @@ fieldset {
     }

     &[selected="true"] {
-      color: var(--in-content-item-selected-text);
-      background-color: var(--in-content-item-selected);
+      color: var(--text-color-accent-primary-selected);
